-- ====================================================================
-- SUPABASE COMPLETE SCHEMA & INITIAL DATA FOR CRMFORU
-- Run this in Supabase Dashboard -> SQL Editor -> Click "Run"
-- ====================================================================

-- 1. USERS TABLE (Multi-User authentication & team access with RBAC)
CREATE TABLE IF NOT EXISTS "users" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"name" varchar(150) NOT NULL,
	"email" varchar(255) NOT NULL UNIQUE,
	"password_hash" varchar(255) NOT NULL,
	"role" varchar(50) DEFAULT 'superadmin' NOT NULL,
	"phone" varchar(50),
	"status" varchar(20) DEFAULT 'active' NOT NULL,
	"province" varchar(100) DEFAULT 'KALIMANTAN BARAT',
	"city" varchar(100) DEFAULT 'KOTA PONTIANAK',
	"district" varchar(100),
	"last_login_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

-- 2. ACTIVITIES TABLE
CREATE TABLE IF NOT EXISTS "activities" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"user_id" bigint NOT NULL,
	"title" varchar(255) NOT NULL,
	"category" varchar(100) DEFAULT 'Umum' NOT NULL,
	"location" varchar(255),
	"pic_name" varchar(150),
	"status" smallint DEFAULT 1 NOT NULL,
	"start_date" timestamp with time zone NOT NULL,
	"end_date" timestamp with time zone,
	"checklist" jsonb DEFAULT '[]'::jsonb,
	"total_estimated_budget" numeric(15, 2) DEFAULT '0' NOT NULL,
	"total_actual_budget" numeric(15, 2) DEFAULT '0' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone
);

CREATE INDEX IF NOT EXISTS "idx_activities_user_start_id" ON "activities" ("user_id", "start_date", "id");

-- 3. BUDGET ITEMS TABLE
CREATE TABLE IF NOT EXISTS "budget_items" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"activity_id" bigint NOT NULL REFERENCES "activities"("id") ON DELETE CASCADE,
	"category" varchar(100) NOT NULL,
	"item_name" varchar(255) NOT NULL,
	"qty" numeric(10, 2) DEFAULT '1' NOT NULL,
	"unit" varchar(50) NOT NULL,
	"unit_price" numeric(15, 2) DEFAULT '0' NOT NULL,
	"estimated_subtotal" numeric(15, 2) DEFAULT '0' NOT NULL,
	"actual_subtotal" numeric(15, 2) DEFAULT '0' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS "idx_budget_items_activity" ON "budget_items" ("activity_id");

-- 4. DOCUMENTS TABLE
CREATE TABLE IF NOT EXISTS "documents" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"activity_id" bigint REFERENCES "activities"("id") ON DELETE SET NULL,
	"user_id" bigint NOT NULL,
	"doc_number" varchar(100) NOT NULL,
	"doc_type" smallint NOT NULL,
	"subject" varchar(255) NOT NULL,
	"recipient_name" varchar(255) NOT NULL,
	"content_payload" jsonb NOT NULL,
	"issued_date" date NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone
);

CREATE INDEX IF NOT EXISTS "idx_documents_user_id" ON "documents" ("user_id");
CREATE INDEX IF NOT EXISTS "idx_documents_activity_id" ON "documents" ("activity_id");

-- 5. AUTOFILL DICTIONARY TABLE
CREATE TABLE IF NOT EXISTS "autofill_dictionary" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"user_id" bigint NOT NULL,
	"field_type" varchar(50) NOT NULL,
	"value_text" varchar(255) NOT NULL,
	"metadata" jsonb,
	"usage_count" integer DEFAULT 1 NOT NULL,
	"last_used_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "uq_autofill_user_field_value" UNIQUE("user_id", "field_type", "value_text")
);

CREATE INDEX IF NOT EXISTS "idx_autofill_lookup" ON "autofill_dictionary" ("user_id", "field_type");

-- 6. DOCUMENT TEMPLATES TABLE
CREATE TABLE IF NOT EXISTS "document_templates" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"user_id" bigint NOT NULL,
	"name" varchar(150) NOT NULL,
	"doc_type" smallint DEFAULT 1 NOT NULL,
	"show_kop" boolean DEFAULT true NOT NULL,
	"header_org_name" varchar(255),
	"header_org_sub" varchar(255),
	"header_org_address" text,
	"header_contact" varchar(255),
	"paper_size" varchar(10) DEFAULT 'A4' NOT NULL,
	"default_opening" text,
	"default_closing" text,
	"signer_title" varchar(150),
	"signer_name" varchar(150),
	"signer_nip" varchar(100),
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

-- 7. PARTY MEMBERS TABLE
CREATE TABLE IF NOT EXISTS "party_members" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"source_id" varchar(100),
	"kta_number" varchar(50) NOT NULL UNIQUE,
	"name" varchar(255) NOT NULL,
	"nik" varchar(25),
	"gender" varchar(20),
	"birth_place" varchar(100),
	"birth_date" date,
	"marital_status" varchar(50),
	"nationality" varchar(50) DEFAULT 'Indonesia',
	"job" varchar(100),
	"email" varchar(255),
	"is_email_verified" boolean DEFAULT false,
	"phone" varchar(50),
	"province" varchar(100) DEFAULT 'KALIMANTAN BARAT',
	"city" varchar(100) DEFAULT 'KOTA PONTIANAK',
	"district" varchar(100),
	"subdistrict" varchar(100),
	"address" text,
	"postal_code" varchar(20),
	"position" varchar(100) DEFAULT 'regular' NOT NULL,
	"membership_status" varchar(50) DEFAULT 'Aktif',
	"org_verification_status" varchar(100) DEFAULT 'Belum Terverifikasi',
	"dpp_validation_status" varchar(100) DEFAULT 'Belum Divalidasi DPP',
	"dpp_decision_date" timestamp with time zone,
	"kpu_status_change_date" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS "idx_party_members_district_subdistrict" ON "party_members" ("district", "subdistrict");
CREATE INDEX IF NOT EXISTS "idx_party_members_position" ON "party_members" ("position");
CREATE INDEX IF NOT EXISTS "idx_party_members_nik" ON "party_members" ("nik");

-- 8. SAMPLE TODOS TABLE (From Supabase Quickstart)
CREATE TABLE IF NOT EXISTS "todos" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
	"name" text NOT NULL,
	"is_complete" boolean DEFAULT false,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

-- ====================================================================
-- ROW LEVEL SECURITY (RLS) POLICIES
-- ====================================================================
ALTER TABLE "users" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "activities" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "budget_items" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "documents" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "autofill_dictionary" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "document_templates" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "party_members" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "todos" ENABLE ROW LEVEL SECURITY;

-- Allow full access for development/authenticated & anon
DO $$
BEGIN
  -- Users
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'users' AND policyname = 'Allow all access to users') THEN
    CREATE POLICY "Allow all access to users" ON "users" FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Activities
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'activities' AND policyname = 'Allow all access to activities') THEN
    CREATE POLICY "Allow all access to activities" ON "activities" FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Budget items
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'budget_items' AND policyname = 'Allow all access to budget_items') THEN
    CREATE POLICY "Allow all access to budget_items" ON "budget_items" FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Documents
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'documents' AND policyname = 'Allow all access to documents') THEN
    CREATE POLICY "Allow all access to documents" ON "documents" FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Autofill
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'autofill_dictionary' AND policyname = 'Allow all access to autofill_dictionary') THEN
    CREATE POLICY "Allow all access to autofill_dictionary" ON "autofill_dictionary" FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Document templates
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'document_templates' AND policyname = 'Allow all access to document_templates') THEN
    CREATE POLICY "Allow all access to document_templates" ON "document_templates" FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Party members
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'party_members' AND policyname = 'Allow all access to party_members') THEN
    CREATE POLICY "Allow all access to party_members" ON "party_members" FOR ALL USING (true) WITH CHECK (true);
  END IF;
  -- Todos
  IF NOT EXISTS (SELECT 1 FROM pg_policies WHERE tablename = 'todos' AND policyname = 'Allow all access to todos') THEN
    CREATE POLICY "Allow all access to todos" ON "todos" FOR ALL USING (true) WITH CHECK (true);
  END IF;
END $$;

